// Noud : Pr�parer image(s) - v2 multi-images
// Supporte imageDataUrls[] (array, widget 0.7+) et imageDataUrl (single, compat 0.6).
// Convertit chaque base64 en binaire nomm� data0, data1... pour AI Agent passthrough vision.
// Transparent si aucune image : retourne l'item sans modification.
const item = $input.first();
const arr = item?.json?.imageDataUrls;
const single = item?.json?.imageDataUrl;
const urls = (Array.isArray(arr) && arr.length > 0)
  ? arr
  : (single && typeof single === 'string' && single.startsWith('data:image/') ? [single] : []);

if (urls.length === 0) { return $input.all(); }

const extMap = { 'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif' };
const binary = {};

for (let i = 0; i < urls.length; i++) {
  const match = String(urls[i]).match(/^data:(image\/[a-zA-Z0-9+.-]+);base64,(.+)$/);
  if (!match) continue;
  const mimeType = match[1];
  const base64Data = match[2];
  if (base64Data.length > 4 * 1024 * 1024) continue;
  const ext = extMap[mimeType] || 'jpg';
  binary['data' + i] = {
    data: base64Data,
    mimeType: mimeType,
    fileName: 'capture_obc_' + (i + 1) + '.' + ext,
    fileSize: Math.round(base64Data.length * 0.75),
    fileExtension: ext
  };
}

if (Object.keys(binary).length === 0) { return $input.all(); }
return [{ json: item.json, binary: binary }];

